import {WAR_RACKS} from './war-rack-catalog.js';import {matchesTarget,planRack,applyRack} from './war-rack-core.js';
export function filterRacks(catalog,{track,stage='all',source='all',genre='all',query=''}={}){const q=query.trim().toLowerCase();return catalog.filter(r=>matchesTarget(r,track)&&(stage==='all'||r.stage===stage)&&(source==='all'||r.source===source)&&(genre==='all'||r.genre===genre||r.genre==='Tous')&&[r.name,r.source,r.genre,r.description].join(' ').toLowerCase().includes(q));}
export function mountRackBrowser(root,{track,project,apply}){root.innerHTML='<div class="mix-master-template-picker"><p>Un preset = une chaîne native ordonnée. Les paramètres restent modifiables dans les fenêtres individuelles.</p><div class="mix-master-template-filters"><label>Étape<select data-stage></select></label><label>Source<select data-source></select></label><label>Genre<select data-genre></select></label><label>Recherche<input type="search" data-query></label></div><div class="mix-master-template-content"><div data-list class="mix-master-template-list"></div><section class="mix-master-template-detail"><h3 data-name></h3><p data-desc></p><ol data-chain></ol><label>Mode<select data-mode><option value="replace">Remplacer</option><option value="append">Ajouter</option></select></label><button type="button" class="primary-btn" data-apply>Appliquer le rack</button><p role="status"></p></section></div></div>';const $=s=>root.querySelector(s),stage=$('[data-stage]'),source=$('[data-source]'),genre=$('[data-genre]'),mode=$('[data-mode]'),button=$('[data-apply]'),status=$('[role=status]');const candidates=WAR_RACKS.filter(r=>matchesTarget(r,track));const fill=(el,values)=>{el.replaceChildren(new Option('Tous','all'),...values.map(v=>new Option(v,v)))};fill(stage,[...new Set(candidates.map(r=>r.stage))]);fill(source,[...new Set(candidates.map(r=>r.source))].sort());fill(genre,[...new Set(candidates.map(r=>r.genre))].sort());if(!track)mode.disabled=true;let selected=null;function render(){const rows=filterRacks(WAR_RACKS,{track,stage:stage.value,source:source.value,genre:genre.value,query:$('[data-query]').value});if(!rows.includes(selected))selected=rows[0]||null;$('[data-list]').replaceChildren(...rows.map(r=>{const b=document.createElement('button');b.className='mix-master-template-option';b.type='button';b.textContent=r.name+' · '+r.source;b.setAttribute('aria-pressed',String(r===selected));b.onclick=()=>{selected=r;render()};return b}));$('[data-name]').textContent=selected?.name||'Aucun rack';$('[data-desc]').textContent=selected?.description||'';$('[data-chain]').replaceChildren();button.disabled=true;status.textContent='';if(!selected)return;try{const plan=planRack(selected,{track,project,mode:mode.value});for(const p of plan.stages){const li=document.createElement('li');li.textContent=p.name+' — '+Object.entries(p.values).map(([k,v])=>k+': '+v).join(' · ');$('[data-chain]').append(li)}status.textContent=plan.stages.length+' plugins / '+plan.available+' places';button.disabled=false}catch(e){status.textContent=e.message}}for(const el of [stage,source,genre,mode])el.onchange=render;$('[data-query]').oninput=render;button.onclick=async()=>{button.disabled=true;try{await apply(selected,mode.value,applyRack)}catch(e){status.textContent=e.message}finally{button.disabled=false}};render();}